const KERN = new Map(
  KERN_PAIRS.split(" ").map((p) => [p.slice(0, 2), -Number(p.slice(2)) / 1000]),
);
const TRACK = -0.03;
const LOOSE = 0.07;
// Manrope typo metrics (USE_TYPO_METRICS): ascender 2132, descender 600 / 2000.
const ASC = 1.066;
const LINE = 1.366;

// The remocn R mark, sized as in the site logo: 0.76em tall on the baseline,
// 0.04em of air before the next letter.
const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";
const R_H = 0.76;
const R_W = (R_H * 124.06) / 134.26;
const R_GAP = 0.04;

const HOP_AT = 20;
const LIFT = 0.24;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam" palette: #f4f7ff, #8fb4ff, #3d5bff, #1a1660 on #02030a.
// It lights a floor the letters land on.
const THEMES = {
  dark: {
    bg: "#02030A",
    fg: "#F4F5F8",
    floor: [
      "rgba(143,180,255,0.62)",
      "rgba(61,91,255,0.5)",
      "rgba(26,22,96,0.55)",
      "rgba(2,3,10,0)",
    ],
    grain: 0.07,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    floor: [
      "rgba(61,91,255,0.6)",
      "rgba(143,180,255,0.62)",
      "rgba(143,180,255,0.3)",
      "rgba(143,180,255,0.1)",
    ],
    grain: 0.045,
  },
} as const;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? MANROPE_500[code - 32] : 620) / 1000;
}

function inkCenter(ch: string) {
  const code = ch.charCodeAt(0);
  const box = code > 32 && code < 127 ? INK_500[code - 33] : null;
  return box ? (box[0] + box[2]) / 2 : advance(ch) / 2;
}

/** Landing squash: a one-frame hit, then a damped return with a hair of overshoot. */
function squash(d: number) {
  if (d < 0 || d > 14) return 0;
  if (d < 1) return d;
  const k = d - 1;
  return Math.exp(-k / 2.4) * Math.cos(k * 0.62);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={31}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function LetterRelayBase({
  word = "remocn",
  hop = 10,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  lift: liftK = LIFT,
  floor = true,
  scale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
  mark = true,
}: LetterRelayProps) {
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const glide = useGlide();
  const { width: W, height: H } = useSceneConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.fg;

  const chars = useMemo(() => Array.from(word), [word]);
  const n = chars.length;
  const useMark = mark && (chars[0] === "r" || chars[0] === "R");
  const isMark = (i: number) => useMark && i === 0;

  const layout = useMemo(() => {
    const xs: number[] = [];
    let x = 0;
    chars.forEach((ch, i) => {
      if (i > 0 && !(useMark && i === 1)) x += KERN.get(chars[i - 1] + ch) ?? 0;
      xs.push(x);
      x += useMark && i === 0 ? R_W + R_GAP - TRACK : advance(ch) + TRACK;
    });
    const total = x - TRACK;
    const tight = xs.map((v) => v - total / 2);
    const spread = (n - 1) * LOOSE;
    const loose = tight.map((v, i) => v + i * LOOSE - spread / 2);
    return { tight, loose, wide: total + spread };
  }, [chars, n, useMark]);

  const F = Math.min(H * 0.34, (W * 0.66) / Math.max(layout.wide, 0.1));
  const baseline = H / 2 + F * 0.3;

  const lastLand = HOP_AT + n * hop;
  const settle = interpolate(t, [lastLand + 1, lastLand + 19], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // The beam pool drifts a little toward whichever letter is in the air.
  const active = Math.min(n - 1, Math.max(0, (t - HOP_AT) / hop));
  const lo = Math.floor(active);
  const hi = Math.min(n - 1, lo + 1);
  const xAt = (i: number) =>
    layout.loose[i] + (layout.tight[i] - layout.loose[i]) * settle;
  const activeX = xAt(lo) + (xAt(hi) - xAt(lo)) * (active - lo);
  const drift = interpolate(t, [lastLand, lastLand + 30], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // The floor stays out of the scale layer (it runs to the frame's edges), so
  // it follows the scaled baseline instead.
  const poolX = 50 + ((activeX * F) / W) * 100 * 0.22 * drift * scale;
  const floorTop =
    scale === 1
      ? baseline + F * 0.09
      : H / 2 + (baseline + F * 0.09 - H / 2) * scale;
  const mask = `radial-gradient(58% 140% at ${poolX}% 0%, #000 35%, transparent 100%)`;
  const poolIn = interpolate(t, [0, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? c.bg),
        overflow: "hidden",
      }}
    >
      {floor ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: floorTop,
            bottom: 0,
            opacity: poolIn,
            background: `linear-gradient(180deg, ${c.floor[0]} 0%, ${c.floor[1]} 4%, ${c.floor[2]} 38%, ${c.floor[3]} 100%)`,
            maskImage: mask,
            WebkitMaskImage: mask,
          }}
        />
      ) : null}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: W / 2,
            top: baseline,
            fontFamily,
            fontWeight: 500,
            fontSize: F,
            fontKerning: "none",
          }}
        >
          {chars.map((ch, i) => {
            const last = i === n - 1;
            const start = HOP_AT + i * hop;
            const land = start + hop;

            const lift = F * liftK * (last ? 1.25 : 1);
            const poseAt = (tt: number) => {
              const enter = interpolate(tt, [i * 2, i * 2 + 14], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const p = interpolate(tt, [start, land], [0, 1], CLAMP);
              const air = p > 0 && p < 1;
              const arc = air ? 4 * p * (1 - p) : 0;
              const crouch = interpolate(tt, [start - 3, start], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const release = interpolate(p, [0, 0.2], [1, 0], CLAMP);
              const stretch = air ? 0.11 * Math.sin(Math.PI * p) * (1 - p) : 0;
              const hit = squash(tt - land) * 0.085;
              return {
                enter,
                p,
                air,
                y: -lift * arc + (1 - enter) * F * 0.16,
                sy: 1 - 0.06 * crouch * release + stretch - hit,
                sx: 1 + 0.04 * crouch * release - stretch * 0.6 + hit * 0.7,
              };
            };
            const { enter, p, air, y, sx, sy } = poseAt(t);
            // A scale step is weighed by the glyph's height above its origin.
            const shifts = (o: ReturnType<typeof poseAt>) =>
              Math.abs(o.y - y) > 1e-3 ||
              Math.abs(o.sx - sx) * F > 1e-3 ||
              Math.abs(o.sy - sy) * F > 1e-3;
            const moving = shifts(poseAt(t + 1)) || shifts(poseAt(t - 1));

            const rot = air ? 5 * Math.sin(Math.PI * p) * (1 - 0.35 * p) : 0;

            const take = interpolate(t, [start - 2, start + 2], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const give = last
              ? 0
              : interpolate(t, [land - 1, land + 5], [0, 1], {
                  ...CLAMP,
                  easing: EASE_OUT,
                });
            const color = interpolateColors(
              take * (1 - give),
              [0, 1],
              [fg, accent],
            );

            const ox = isMark(i) ? R_W / 2 : inkCenter(ch);
            const x = (xAt(i) + ox) * F;

            return (
              <div
                key={`${i}-${ch}`}
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  color,
                  opacity: enter,
                  transformOrigin: "0 0",
                  transform: `translate(${x}px, ${y}px) rotate(${rot}deg) scale(${sx}, ${sy})${glide(moving)}`,
                }}
              >
                {isMark(i) ? (
                  <svg
                    viewBox="0 0 124.06 134.26"
                    width={R_W * F}
                    height={R_H * F}
                    style={{
                      position: "absolute",
                      left: -ox * F,
                      top: -R_H * F,
                      display: "block",
                    }}
                    aria-hidden
                  >
                    <path fill="currentColor" d={REMOCN_R_PATH} />
                  </svg>
                ) : (
                  <span
                    style={{
                      position: "absolute",
                      left: -ox * F,
                      top: -ASC * F,
                      lineHeight: LINE,
                      whiteSpace: "pre",
                    }}
                  >
                    {ch}
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

